// prisma/seed-week-curriculum.ts — Full week curriculum data for 6 classes (130 lessons)
// Each lesson has rich Liberian-context content for the MOE pilot demo.

export type WeekLesson = {
  contentId: string;
  grade: number;
  subject: string;
  day: number; // 0=Mon..4=Fri
  periodNumber: number;
  startTime: string;
  endTime: string;
  title: string;
  payload: Record<string, unknown>;
};

export type ClassSchedule = {
  classId: string;
  teacherEmail: string;
  lessons: WeekLesson[];
};

// Helper to build a standard lesson payload
function lesson(p: {
  title: string; body: string; objectives: string[]; activities: string[];
  homework: string; assessQ: string; assessOpts: string[]; assessAns: string;
  labs?: any[]; weeklyReview?: string; masteryChecks?: any[];
}): Record<string, unknown> {
  const out: Record<string, unknown> = {
    title: p.title, body: p.body, objectives: p.objectives, activities: p.activities,
    homework: p.homework,
    assessment: { question: p.assessQ, options: p.assessOpts, correctAnswer: p.assessAns },
    durationMins: 45,
  };
  if (p.labs) out.labs = p.labs;
  if (p.weeklyReview) out.weeklyReview = p.weeklyReview;
  if (p.masteryChecks) out.masteryChecks = p.masteryChecks;
  return out;
}

